<?php if(allow(['sales','production'])):?><details class="panel editor" id="editor" <?=($edit||isset($_GET['new']))?'open':''?>><summary><?=$edit?'Editar fornecedor':'Cadastrar fornecedor'?></summary><div class="editor-inner"><form action="<?=e(url('suppliers.save'))?>" method="post"><?=csrf_field()?><input type="hidden" name="_back" value="suppliers"><input name="id" type="hidden" value="<?=e($edit['id']??'')?>"><div class="form-grid cols-3"><div class="field span-2"><label>Nome / Razão social *</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>CNPJ / CPF</label><input name="document" value="<?=e($edit['document']??'')?>"></div><div class="field"><label>Contato responsável</label><input name="contact" value="<?=e($edit['contact']??'')?>"></div><div class="field"><label>Telefone</label><input name="phone" value="<?=e($edit['phone']??'')?>"></div><div class="field"><label>E-mail</label><input type="email" name="email" value="<?=e($edit['email']??'')?>"></div><div class="field span-3"><label>Observações</label><textarea name="notes"><?=e($edit['notes']??'')?></textarea></div></div><div class="form-footer"><button class="btn-aurora">Salvar fornecedor</button><a class="btn-aurora btn-outline-aurora" href="<?=e(url('suppliers'))?>">Cancelar</a></div></form></div></details><?php endif;?>
<div class="panel"><div class="panel-header"><h2>Fornecedores cadastrados</h2><span class="tag"><?=count($suppliers)?> registros</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Fornecedor</th><th>CNPJ / CPF</th><th>Contato</th><th>Telefone</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($suppliers as $s):?><tr><td><strong><?=e($s['name'])?></strong><small><?=e($s['email'])?></small></td><td><?=e($s['document']?:'—')?></td><td><?=e($s['contact']?:'—')?></td><td><?=e($s['phone']?:'—')?></td><td><span class="status-badge <?=$s['active']?'badge-success':'badge-muted'?>"><?=$s['active']?'Ativo':'Arquivado'?></span></td><td><div class="table-actions"><?php if(allow(['sales','production'])):?><a class="btn-aurora btn-outline-aurora btn-sm-aurora" href="<?=e(url('suppliers',['edit'=>$s['id']]))?>#editor"><?=svg_icon('edit',14)?></a><form method="post" action="<?=e(url('suppliers.archive'))?>" data-confirm="Alterar situação deste fornecedor?"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($s['id'])?>"><button class="btn-aurora btn-outline-aurora btn-sm-aurora"><?=$s['active']?'Arquivar':'Ativar'?></button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$suppliers):?><tr><td colspan="6" class="empty">Nenhum fornecedor.</td></tr><?php endif;?></tbody></table></div></div>
